{
  "gateway": "x_ads_native_action",
  "mode": "direct",
  "description": "Complete X Ads API v12 native gateway generated from the local MDFILES/x-ads-api snapshot. Covers accounts, campaigns, line items, promoted Tweets, creatives, cards, media upload/library, audiences, targeting, measurement, analytics, and catalogs. Use action=LIST_ACTIONS for discovery. Writes are dry-run by default.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "action": {
        "type": "string",
        "minLength": 1,
        "description": "Canonical X Ads native action, legacy uppercase action, LIST_ACTIONS, or DESCRIBE_ACTION."
      },
      "target_action": {
        "type": "string",
        "description": "Action to describe when action=DESCRIBE_ACTION."
      },
      "search": {
        "type": "string",
        "description": "LIST_ACTIONS case-insensitive action, alias, category, method, or endpoint filter."
      },
      "category": {
        "type": "string",
        "enum": [
          "account",
          "campaign",
          "creative",
          "audience",
          "targeting",
          "measurement",
          "reporting",
          "catalog"
        ],
        "description": "LIST_ACTIONS category filter."
      },
      "read_only": {
        "type": "boolean",
        "description": "LIST_ACTIONS read/write filter."
      },
      "limit": {
        "type": "integer",
        "minimum": 1,
        "maximum": 500,
        "default": 100,
        "description": "LIST_ACTIONS page size."
      },
      "offset": {
        "type": "integer",
        "minimum": 0,
        "default": 0,
        "description": "LIST_ACTIONS zero-based offset."
      },
      "connection_id": {
        "type": "string",
        "format": "uuid",
        "description": "Optional explicit X OAuth connection ID for users with multiple connected X accounts."
      },
      "account_id": {
        "type": "string",
        "description": "Authorized X Ads account ID. May also be supplied in path_params."
      },
      "path_params": {
        "type": "object",
        "additionalProperties": {},
        "description": "Native path placeholders such as account_id, campaign_id, line_item_id, card_id, or scheduled_feed_id."
      },
      "params": {
        "$ref": "#/properties/path_params",
        "description": "Native X query/form parameters. Required path values may also be supplied here or top-level."
      },
      "query": {
        "$ref": "#/properties/path_params",
        "description": "Explicit query parameters; merged after params."
      },
      "payload": {
        "anyOf": [
          {
            "type": "object",
            "additionalProperties": {}
          },
          {
            "type": "array",
            "items": {}
          },
          {
            "type": "string",
            "maxLength": 4194304
          }
        ],
        "description": "Native request body. Accepts an object, batch array, or stringified JSON object/array for cached-client compatibility."
      },
      "confirmed": {
        "type": "boolean",
        "default": false,
        "description": "Required with dry_run:false for DELETE actions."
      },
      "dry_run": {
        "type": "boolean",
        "description": "Writes default to dry-run. Set false to execute after reviewing the request."
      },
      "idempotency_key": {
        "type": "string",
        "format": "uuid",
        "description": "Recommended for live writes."
      },
      "result_fields": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Optional response projection. Provider error and partial-failure envelopes are always preserved."
      },
      "max_items": {
        "type": "integer",
        "minimum": 1,
        "maximum": 10000,
        "description": "Maximum items returned from each result array."
      },
      "compact": {
        "type": "boolean",
        "description": "Remove empty values while preserving provider failures and pagination metadata."
      }
    },
    "required": [
      "action"
    ],
    "additionalProperties": true,
    "$schema": "http://json-schema.org/draft-07/schema#"
  },
  "operation_count": 186,
  "usage": "Call x_ads_native_action with action=LIST_ACTIONS, or call whathead_tool_help again with operation=<canonical X action> for exact endpoint and path fields."
}
